// ---- LOGIQUE REGLEMENT SPECIAL ----
function checkRulesEnforcement(rulesEnabled) {
    if (!userPseudo) return; // not logged in
    const modal = document.getElementById('rules-modal');
    if (!modal) return;
    
    // Si la règle est activée et que l'utilisateur n'a pas accepté
    if (rulesEnabled && window.hasAcceptedRules === false) {
        modal.classList.remove('hidden');
    } else {
        modal.classList.add('hidden');
    }
}

document.addEventListener('DOMContentLoaded', () => {
    const rulesContent = document.getElementById('rules-content');
    const acceptBtn = document.getElementById('accept-rules-btn');
    
    if (rulesContent && acceptBtn) {
        rulesContent.addEventListener('scroll', () => {
            // Si on est à moins de 10 pixels du bas
            if (rulesContent.scrollTop + rulesContent.clientHeight >= rulesContent.scrollHeight - 10) {
                acceptBtn.disabled = false;
                acceptBtn.style.cursor = 'pointer';
                acceptBtn.style.opacity = '1';
                acceptBtn.style.backgroundColor = '#2ecc71';
            }
        });
        
        acceptBtn.addEventListener('click', async () => {
            try {
                const res = await fetch('/api/rules/accept', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json', 'pseudo': userPseudo, 'password': userPassword }
                });
                if (res.ok) {
                    window.hasAcceptedRules = true;
                    document.getElementById('rules-modal').classList.add('hidden');
                }
            } catch (e) {
                console.error("Erreur validation reglement", e);
            }
        });
    }
});
